     1	package com.loja.orders.shipping;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	
     6	import org.springframework.http.HttpStatus;
     7	
     8	import com.loja.orders.common.ApiException;
     9	import com.loja.orders.common.ErrorCode;
    10	import com.loja.orders.shipping.carrier.Carrier;
    11	import com.loja.orders.shipping.carrier.CarrierQuote;
    12	import com.loja.orders.shipping.carrier.CarrierService;
    13	import com.loja.orders.shipping.carrier.CarrierUnavailableException;
    14	import com.loja.orders.shipping.carrier.ZipNotServedException;
    15	
    16	/** Entrega feita por transportadora: o frete e o prazo vêm dela, mais o tempo de despacho da região. */
    17	public abstract class CarrierShippingOption implements ShippingOption {
    18	
    19	    private static final BigDecimal GRAMS_PER_KG = new BigDecimal("1000");
    20	    private static final int HOURS_PER_DAY = 24;
    21	
    22	    private final Carrier carrier;
    23	    private final CarrierService service;
    24	
    25	    protected CarrierShippingOption(Carrier carrier, CarrierService service) {
    26	        this.carrier = carrier;
    27	        this.service = service;
    28	    }
    29	
    30	    @Override
    31	    public ShippingQuote quote(ShippingRequest request) {
    32	        int weightGrams = request.weightKg().multiply(GRAMS_PER_KG).setScale(0, RoundingMode.CEILING).intValueExact();
    33	        CarrierQuote quote;
    34	        try {
    35	            quote = carrier.quote(request.zipCode(), weightGrams, service);
    36	        } catch (ZipNotServedException e) {
    37	            throw ApiException.unprocessable(ErrorCode.SHIPPING_METHOD_UNAVAILABLE);
    38	        } catch (CarrierUnavailableException e) {
    39	            throw new ApiException(HttpStatus.SERVICE_UNAVAILABLE, ErrorCode.CARRIER_UNAVAILABLE);
    40	        }
    41	        int days = Math.ceilDiv(quote.etaHours(), HOURS_PER_DAY) + request.region().carrierDispatchExtraDays();
    42	        return new ShippingQuote(quote.price(), days);
    43	    }
    44	}
